def h(schluessel, groesse):
    summe = 0
    for z in schluessel:
        summe += ord(z)  # Zeichencode
    return summe % groesse

class HashTabelle:
    def __init__(self, groesse=7):
        self.buckets = [[] for _ in
                        range(groesse)]

    def put(self, key, wert):
        i = h(key, len(self.buckets))
        bucket = self.buckets[i]
        for j, (k, _) in enumerate(bucket):
            if k == key:   # überschreiben
                bucket[j] = (key, wert)
                return
        bucket.append((key, wert))

    def get(self, key):
        i = h(key, len(self.buckets))
        for k, w in self.buckets[i]:
            if k == key:
                return w
        raise KeyError(key)

t = HashTabelle()
t.put("Anna", 1)
t.put("Ben", 2)
print(t.buckets[4])
# [('Anna', 1), ('Ben', 2)]
print(t.get("Ben"))   # 2

